from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any

from .errors import ValidationError

# The largest loop max_iterations a declaration may request; larger values are
# a validation error.
MAX_LOOP_ITERATIONS = 100
# The largest node or template retries value a declaration may request; the
# allowed range is 0 through this value.
MAX_RETRIES = 10


def _identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 100:
        raise ValidationError(f"{field} must be a non-empty string of at most 100 characters")
    return value


def _input_path(value: Any) -> str:
    if not isinstance(value, str) or not value or any(not segment for segment in value.split(".")):
        raise ValidationError("path must be a non-empty dot-separated input path")
    return value


def _finite_json(value: Any, field: str) -> Any:
    if isinstance(value, float) and not math.isfinite(value):
        raise ValidationError(f"{field} must not contain non-finite numbers")
    if isinstance(value, dict):
        for item in value.values():
            _finite_json(item, field)
    elif isinstance(value, list):
        for item in value:
            _finite_json(item, field)
    return value


def _json_scalar(value: Any, field: str) -> Any:
    if isinstance(value, (dict, list)):
        raise ValidationError(f"{field} must be a JSON scalar")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValidationError(f"{field} must be a finite JSON scalar")
    return value


@dataclass(frozen=True)
class RunIf:
    condition_id: str
    expected: bool

    @classmethod
    def parse(cls, raw: Any) -> "RunIf":
        if not isinstance(raw, dict) or set(raw) != {"condition_id", "expected"}:
            raise ValidationError("run_if must contain exactly condition_id and expected")
        condition_id = _identifier(raw["condition_id"], "condition id")
        if not isinstance(raw["expected"], bool):
            raise ValidationError("run_if expected must be a boolean")
        return cls(condition_id, raw["expected"])

    def as_dict(self) -> dict[str, Any]:
        return {"condition_id": self.condition_id, "expected": self.expected}


@dataclass(frozen=True)
class Approval:
    approvers: tuple[str, ...]

    @classmethod
    def parse(cls, raw: Any) -> "Approval":
        if not isinstance(raw, dict) or set(raw) != {"approvers"}:
            raise ValidationError("approval must contain exactly approvers")
        approvers = raw["approvers"]
        if not isinstance(approvers, list) or not approvers:
            raise ValidationError("approval approvers must be a non-empty array")
        if any(not isinstance(item, str) for item in approvers):
            raise ValidationError("approval approvers must be strings")
        if len(approvers) != len(set(approvers)):
            raise ValidationError("approval approvers must not contain duplicates")
        return cls(tuple(approvers))

    def as_dict(self) -> dict[str, Any]:
        return {"approvers": list(self.approvers)}


@dataclass(frozen=True)
class MapTemplate:
    """The per-instance task a map node expands into.

    A template carries only a task identifier, a retry bound, and an optional
    approval point: instances are ready tasks like any other, distinguished
    only by their map node and element index.
    """

    task_id: str
    retries: int | None
    approval: Approval | None = None

    @classmethod
    def parse(cls, raw: Any) -> "MapTemplate":
        if not isinstance(raw, dict) or not set(raw) <= {"id", "retries", "approval"}:
            raise ValidationError("map template may only contain id, retries, and approval")
        if "id" not in raw:
            raise ValidationError("map template must contain an id")
        task_id = _identifier(raw["id"], "map template id")
        retries = raw["retries"] if "retries" in raw else None
        if retries is not None:
            if isinstance(retries, bool) or not isinstance(retries, int):
                raise ValidationError("map template retries must be an integer")
            if not 0 <= retries <= MAX_RETRIES:
                raise ValidationError(f"map template retries must be between 0 and {MAX_RETRIES}")
        approval = Approval.parse(raw["approval"]) if "approval" in raw else None
        return cls(task_id, retries, approval)

    def as_dict(self) -> dict[str, Any]:
        document: dict[str, Any] = {"id": self.task_id}
        if self.retries is not None:
            document["retries"] = self.retries
        if self.approval is not None:
            document["approval"] = self.approval.as_dict()
        return document


@dataclass(frozen=True)
class Node:
    id: str
    kind: str
    depends_on: tuple[str, ...]
    path: str | None = None
    equals: Any = None
    run_if: RunIf | None = None
    retries: int | None = None
    approval: Approval | None = None
    entry: str | None = None
    condition: str | None = None
    max_iterations: int | None = None
    source: str | None = None
    max_instances: int | None = None
    template: MapTemplate | None = None

    @classmethod
    def parse(cls, raw: Any) -> "Node":
        if not isinstance(raw, dict):
            raise ValidationError("each node must be an object")
        kind = raw.get("kind")
        if kind not in ("task", "condition", "loop", "map"):
            raise ValidationError("node kind must be task, condition, loop, or map")
        base = {"id", "kind", "depends_on"}
        if not base <= set(raw):
            raise ValidationError("each node must contain id, kind, and depends_on")
        node_id = _identifier(raw["id"], "node id")
        dependencies = raw["depends_on"]
        if not isinstance(dependencies, list) or any(not isinstance(item, str) for item in dependencies):
            raise ValidationError("depends_on must be an array of node identifiers")
        if len(dependencies) != len(set(dependencies)):
            raise ValidationError("depends_on must not contain duplicates")
        depends_on = tuple(dependencies)
        if kind == "task":
            if not set(raw) - base <= {"run_if", "retries", "approval"}:
                raise ValidationError("task nodes may only contain id, kind, depends_on, run_if, retries, and approval")
            run_if = RunIf.parse(raw["run_if"]) if "run_if" in raw else None
            retries = raw.get("retries")
            if retries is not None:
                if isinstance(retries, bool) or not isinstance(retries, int):
                    raise ValidationError("retries must be an integer")
                if not 0 <= retries <= MAX_RETRIES:
                    raise ValidationError(f"retries must be between 0 and {MAX_RETRIES}")
            approval = Approval.parse(raw["approval"]) if "approval" in raw else None
            return cls(node_id, "task", depends_on, run_if=run_if, retries=retries, approval=approval)
        if kind == "loop":
            if set(raw) != base | {"entry", "condition", "max_iterations"}:
                raise ValidationError("loop nodes must contain exactly id, kind, depends_on, entry, condition, and max_iterations")
            max_iterations = raw["max_iterations"]
            if isinstance(max_iterations, bool) or not isinstance(max_iterations, int):
                raise ValidationError("max_iterations must be an integer")
            if not 1 <= max_iterations <= MAX_LOOP_ITERATIONS:
                raise ValidationError(f"max_iterations must be between 1 and {MAX_LOOP_ITERATIONS}")
            return cls(
                node_id,
                "loop",
                depends_on,
                entry=_identifier(raw["entry"], "entry"),
                condition=_identifier(raw["condition"], "condition"),
                max_iterations=max_iterations,
            )
        if kind == "map":
            required = {"source", "path", "max_instances", "template"}
            if set(raw) != base | required:
                raise ValidationError(
                    "map nodes must contain exactly id, kind, depends_on, source, path, max_instances, and template"
                )
            source = _identifier(raw["source"], "map source")
            element_path = _input_path(raw["path"])
            max_instances = raw["max_instances"]
            if isinstance(max_instances, bool) or not isinstance(max_instances, int):
                raise ValidationError("max_instances must be an integer")
            if max_instances < 1:
                raise ValidationError("max_instances must be a positive integer")
            template = MapTemplate.parse(raw["template"])
            return cls(
                node_id,
                "map",
                depends_on,
                path=element_path,
                source=source,
                max_instances=max_instances,
                template=template,
            )
        if set(raw) != base | {"path", "equals"}:
            raise ValidationError("condition nodes must contain exactly id, kind, depends_on, path, and equals")
        return cls(
            node_id,
            "condition",
            depends_on,
            path=_input_path(raw["path"]),
            equals=_json_scalar(raw["equals"], "equals"),
        )

    def as_dict(self) -> dict[str, Any]:
        document: dict[str, Any] = {"id": self.id, "kind": self.kind, "depends_on": list(self.depends_on)}
        if self.kind == "condition":
            document["path"] = self.path
            document["equals"] = self.equals
        elif self.kind == "loop":
            document["entry"] = self.entry
            document["condition"] = self.condition
            document["max_iterations"] = self.max_iterations
        elif self.kind == "map":
            document["source"] = self.source
            document["path"] = self.path
            document["max_instances"] = self.max_instances
            document["template"] = self.template.as_dict()
        else:
            if self.run_if is not None:
                document["run_if"] = self.run_if.as_dict()
            if self.retries is not None:
                document["retries"] = self.retries
            if self.approval is not None:
                document["approval"] = self.approval.as_dict()
        return document


@dataclass(frozen=True)
class Workflow:
    id: str
    nodes: tuple[Node, ...]

    @classmethod
    def parse(cls, raw: Any) -> "Workflow":
        if not isinstance(raw, dict) or set(raw) != {"id", "nodes"}:
            raise ValidationError("workflow must contain exactly id and nodes")
        workflow_id = _identifier(raw["id"], "workflow id")
        if not isinstance(raw["nodes"], list) or not raw["nodes"]:
            raise ValidationError("nodes must be a non-empty array")
        nodes = tuple(Node.parse(node) for node in raw["nodes"])
        identifiers = {node.id for node in nodes}
        if len(identifiers) != len(nodes):
            raise ValidationError("node identifiers must be unique")
        for node in nodes:
            if node.id in node.depends_on:
                raise ValidationError(f"node {node.id} cannot depend on itself")
            missing = set(node.depends_on) - identifiers
            if missing:
                raise ValidationError(f"node {node.id} has unknown dependencies: {', '.join(sorted(missing))}")
        by_id = {node.id: node for node in nodes}
        for node in nodes:
            if node.run_if is None:
                continue
            target = by_id.get(node.run_if.condition_id)
            if target is None or target.kind != "condition":
                raise ValidationError(f"node {node.id} run_if must reference a condition node")
            if node.run_if.condition_id not in node.depends_on:
                raise ValidationError(f"node {node.id} must list condition {node.run_if.condition_id} in depends_on")
        _assert_acyclic(nodes)
        _assert_valid_loops(nodes, by_id)
        _assert_valid_maps(nodes, by_id)
        return cls(workflow_id, nodes)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "nodes": [node.as_dict() for node in self.nodes]}

    def loop_bodies(self) -> dict[str, frozenset[str]]:
        """Map each loop node id to the set of node ids forming its body."""
        by_id = {node.id: node for node in self.nodes}
        bodies: dict[str, frozenset[str]] = {}
        for node in self.nodes:
            if node.kind == "loop":
                bodies[node.id] = frozenset(_collect_loop_body(by_id, node.entry, node.condition))
        return bodies


def _ancestors(by_id: dict[str, Node], node_id: str) -> set[str]:
    """Every node reachable from node_id by following depends_on edges."""
    found: set[str] = set()
    stack = [node_id]
    while stack:
        current = stack.pop()
        if current in found:
            continue
        found.add(current)
        stack.extend(by_id[current].depends_on)
    return found


def _collect_loop_body(by_id: dict[str, Node], entry: str, condition: str) -> set[str]:
    """The loop body region anchored by its named entry and condition.

    The two anchors name the ends of the repeated segment: the entry task may
    run first with the condition evaluated after it (the condition depends on
    the entry), or the condition may gate the entry task (the entry depends on
    it). Either way the body is the union of what the anchors depend on; the
    anchors are additionally required to be connected (see
    ``_assert_valid_loops``).
    """
    return _ancestors(by_id, entry) | _ancestors(by_id, condition)


def _assert_valid_loops(nodes: tuple[Node, ...], by_id: dict[str, Node]) -> None:
    bodies: dict[str, set[str]] = {}
    for node in nodes:
        if node.kind != "loop":
            continue
        entry = by_id.get(node.entry)
        if entry is None:
            raise ValidationError(f"loop {node.id} entry references an unknown node")
        if entry.kind != "task":
            raise ValidationError(f"loop {node.id} entry must reference a task node")
        judge = by_id.get(node.condition)
        if judge is None:
            raise ValidationError(f"loop {node.id} condition references an unknown node")
        if judge.kind != "condition":
            raise ValidationError(f"loop {node.id} condition must reference a condition node")
        # The condition is inside the repeated segment only when it is connected
        # to the entry: it gates the entry (entry depends on it) or it is
        # evaluated after the entry (it depends on the entry).
        entry_ancestors = _ancestors(by_id, node.entry)
        condition_ancestors = _ancestors(by_id, node.condition)
        if node.condition not in entry_ancestors and node.entry not in condition_ancestors:
            raise ValidationError(f"loop {node.id} condition must belong to the loop body")
        body = _collect_loop_body(by_id, node.entry, node.condition)
        if node.id in body:
            raise ValidationError(f"loop {node.id} entry must not depend on the loop itself")
        if any(by_id[member].kind == "loop" for member in body):
            raise ValidationError(f"loop {node.id} body must not contain another loop")
        if judge.id not in body:
            raise ValidationError(f"loop {node.id} condition must belong to the loop body")
        bodies[node.id] = body
    owner: dict[str, str] = {}
    for loop_id, body in bodies.items():
        for member in body:
            if member in owner:
                raise ValidationError(f"node {member} belongs to more than one loop body")
            owner[member] = loop_id
    for node in nodes:
        if node.id in owner:
            continue
        for dependency in node.depends_on:
            if dependency in owner:
                raise ValidationError(
                    f"node {node.id} must not depend on loop body node {dependency}; depend on loop {owner[dependency]} instead"
                )


def _assert_valid_maps(nodes: tuple[Node, ...], by_id: dict[str, Node]) -> None:
    """Structural rules for dynamic map nodes.

    The expansion source must be a task explicitly listed as a dependency.
    The template's task identifier only names the dynamically expanded
    instances: it may coincide with a declared node identifier or with
    another map's template identifier. A map node may sit inside a loop
    body, expanding independently in every iteration.
    """
    for node in nodes:
        if node.kind != "map":
            continue
        source = by_id.get(node.source)
        if source is None:
            raise ValidationError(f"map {node.id} source references an unknown node")
        if source.kind != "task":
            raise ValidationError(f"map {node.id} source must reference a task node")
        if node.source not in node.depends_on:
            raise ValidationError(f"map {node.id} must list its source task {node.source} in depends_on")


def _assert_acyclic(nodes: tuple[Node, ...]) -> None:
    graph = {node.id: node.depends_on for node in nodes}
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(node_id: str) -> None:
        if node_id in visiting:
            raise ValidationError("workflow contains a dependency cycle")
        if node_id in visited:
            return
        visiting.add(node_id)
        for dependency in graph[node_id]:
            visit(dependency)
        visiting.remove(node_id)
        visited.add(node_id)

    for node_id in graph:
        visit(node_id)

    """Whether a lease's target is still a currently ready, unleased target."""
    ready = self._ready_targets(workflow, state)
    return any(self._target_key(item) == self._target_key(target) for item in ready)

def decision(
    self, execution_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    if not isinstance(raw, dict) or not {"approver", "decision"} <= set(raw) <= {"approver", "decision", "output", "reason"}:
        raise ValidationError("decision body must contain approver and decision, plus output or reason")
    approver = raw["approver"]
    if not isinstance(approver, str):
        raise ValidationError("approver must be a string")
    verdict = raw["decision"]
    if verdict not in ("approved", "rejected"):
        raise ValidationError("decision must be \"approved\" or \"rejected\"")
    if verdict == "approved":
        if set(raw) != {"approver", "decision", "output"}:
            raise ValidationError("an approved decision must contain exactly approver, decision, and output")
        if not isinstance(raw["output"], dict):
            raise ValidationError("decision output must be an object")
        _finite_json(raw["output"], "output")
        output = raw["output"]
        reason = None
    else:
        if set(raw) != {"approver", "decision", "reason"}:
            raise ValidationError("a rejected decision must contain exactly approver, decision, and reason")
        if not isinstance(raw["reason"], str):
            raise ValidationError("decision reason must be a string")
        output = None
        reason = raw["reason"]

    def apply() -> dict[str, Any]:
        state = self.get_execution(execution_id, tenant)
        waiting = state.get("waiting_approval")
        workflow = self._bound_workflow(execution_id, tenant)
        if waiting is None:
            # A duplicate of the decision that already resolved the most
            # recent approval point returns that first result; it neither
            # advances the node again nor appends another event. Any other
            # decision against an execution with no pending point conflicts.
            if self._is_repeated_decision(state, approver, verdict, output, reason):
                return state
            raise ConflictError("execution has no pending approval decision")
        if approver not in waiting["approvers"]:
            raise ConflictError(f"approver {approver} is not allowed to decide this approval point")
        node_id = waiting["node_id"]
        context = self._approval_context(waiting)
        state["waiting_approval"] = None
        state["approvals"].append(
            {"node_id": node_id, "approver": approver, "decision": verdict, "reason": reason, **context}
        )
        payload: dict[str, Any] = {"node_id": node_id, "approver": approver, "decision": verdict, **context}
        if verdict == "rejected":
            payload["reason"] = reason
        self._append(execution_id, "approval_decided", payload, tenant)
        if verdict == "approved":
            target: dict[str, Any] = {"node_id": node_id}
            if "map_id" in waiting:
                target = {"map_id": waiting["map_id"], "node_id": node_id, "index": waiting["index"]}
                if "loop_id" in waiting:
                    target["loop_id"] = waiting["loop_id"]
                    target["iteration"] = waiting["iteration"]
            self._complete_target(execution_id, workflow, state, target, output, tenant)
            if state["status"] == "running":
                self._auto_process(execution_id, workflow, state, tenant)
        elif "map_id" in waiting:
            map_id = waiting["map_id"]
            index = waiting["index"]
            _, map_state, context = self._map_context(state, waiting)
            instance = next(item for item in map_state["instances"] if item["index"] == index)
            instance["status"] = "failed"
            instance["failure_reason"] = reason
            map_state["status"] = "failed"
            map_state["failure_reason"] = reason
            state["failed_nodes"].append(map_id)
            self._terminate(
                execution_id,
                state,
                "rejected",
                tenant,
                {"node_id": map_id, "map_id": map_id, "index": index, **context},
            )
        else:
            state["failed_nodes"].append(node_id)
            self._terminate(execution_id, state, "rejected", tenant, {"node_id": node_id})
        self.store.connection.execute(
            "UPDATE executions SET state = ? WHERE tenant = ? AND id = ?",
            (self.store.encode(state), tenant, execution_id),
        )
        # The decision settles the parked node boundary: completion on
        # approval, permanent failure on rejection.
        self._write_checkpoint(execution_id, state, tenant)
        return state

    with self._operation():
        return self._idempotent(key, f"decision:{execution_id}", apply, tenant)

@staticmethod
def _is_repeated_decision(
    state: dict[str, Any], approver: str, verdict: str, output: Any, reason: str | None
) -> bool:
    records = state.get("approvals") or []
    if not records:
        return False
    record = records[-1]
    if record["approver"] != approver or record["decision"] != verdict:
        return False
    if verdict == "rejected":
        return record["reason"] == reason
    return ChronicleFlow._recorded_output(state, record) == output

@staticmethod
def _map_context(state: dict[str, Any], record: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Locate a map's state and event context from a record naming it.

    A record carrying ``loop_id`` and ``iteration`` names a map nested in
    a loop body: its state lives in that iteration's record. Anything else
    names an execution-level map. Returns the container holding the map's
    progress, the map state itself, and the loop context to stamp on
    events (empty for an execution-level map).
    """
    map_id = record["map_id"]
    if record.get("loop_id") is not None:
        loop_state = state["loops"][record["loop_id"]]
        iteration = loop_state["iterations"][record["iteration"] - 1]
        return iteration, iteration["maps"][map_id], {"loop_id": record["loop_id"], "iteration": record["iteration"]}
    return state, state["maps"][map_id], {}

@staticmethod
def _recorded_output(state: dict[str, Any], record: dict[str, Any]) -> Any:
    if "map_id" in record:
        _, map_state, _ = ChronicleFlow._map_context(state, record)
        instance = next(item for item in map_state["instances"] if item["index"] == record["index"])
        return instance["output"]
    if "loop_id" in record:
        iteration = state["loops"][record["loop_id"]]["iterations"][record["iteration"] - 1]
        return iteration["outputs"].get(record["node_id"])
    return state["outputs"].get(record["node_id"])

@staticmethod
def _approval_context(waiting: dict[str, Any]) -> dict[str, Any]:
    context = {key: waiting[key] for key in ("loop_id", "iteration") if key in waiting}
    if "map_id" in waiting:
        context["map_id"] = waiting["map_id"]
        context["index"] = waiting["index"]
    return context

def _request_approval(
    self, execution_id: str, workflow: Workflow, state: dict[str, Any], target: dict[str, Any], tenant: str
) -> None:
    node_id = target["node_id"]
    if target.get("map_id") is not None:
        map_node = next(node for node in workflow.nodes if node.id == target["map_id"])
        approvers = list(map_node.template.approval.approvers)
    else:
        node = next(node for node in workflow.nodes if node.id == node_id)
        approvers = list(node.approval.approvers)
    waiting: dict[str, Any] = {"node_id": node_id, "approvers": approvers}
    if target.get("map_id") is not None:
        # A map instance carries its expansion context explicitly: the
        # template id is not a declared node, so no loop lookup applies.
        if target.get("loop_id") is not None:
            waiting["loop_id"] = target["loop_id"]
            waiting["iteration"] = target["iteration"]
        waiting["map_id"] = target["map_id"]
        waiting["index"] = target["index"]
        _, map_state, _ = self._map_context(state, target)
        instance = next(
            item
            for item in map_state["instances"]
            if item["index"] == target["index"]
        )
        instance["status"] = "waiting"
    else:
        loop_id = self._active_loop(workflow, state, node_id)
        if loop_id is not None:
            waiting["loop_id"] = loop_id
            waiting["iteration"] = state["loops"][loop_id]["current_iteration"]
    state["waiting_approval"] = waiting
    self._append(
        execution_id,
        "approval_requested",
        {"node_id": node_id, "approvers": approvers, **self._approval_context(waiting)},
        tenant,
    )

def cancel(self, execution_id: str, key: str | None, tenant: str = DEFAULT_TENANT) -> dict[str, Any]:
    def apply() -> dict[str, Any]:
        state = self.get_execution(execution_id, tenant)
        if state["status"] != "running":
            return state
        self._terminate(execution_id, state, "cancelled", tenant)
        self.store.connection.execute(
            "UPDATE executions SET state = ? WHERE tenant = ? AND id = ?",
            (self.store.encode(state), tenant, execution_id),
        )
        return state

    with self._operation():
        return self._idempotent(key, f"cancel:{execution_id}", apply, tenant)

@staticmethod
def _reconcile_state_for_definition(state: dict[str, Any], workflow: Workflow) -> None:
    """Align the materialized summary with a newly bound revision.

    Loops introduced by the new definition start in their initial pending
    state; loops only the previous definition knew keep their recorded
    history untouched, so pre-migration conclusions never change. The
    approval fields exist as soon as the bound definition declares an
    approval point; a parked waiting point is left exactly as recorded.
    """
    for node in workflow.nodes:
        if node.kind == "loop" and node.id not in state["loops"]:
            state["loops"][node.id] = _new_loop_state()
    declared_maps = _declared_map_states(workflow)
    if declared_maps and "maps" not in state:
        state["maps"] = {}
    for map_id, map_state in declared_maps.items():
        if map_id not in state.get("maps", {}):
            state["maps"][map_id] = map_state
    if _has_approval_points(workflow) and "approvals" not in state:
        state["waiting_approval"] = None
        state["approvals"] = []

def migrate(
    self, execution_id: str, raw: Any, key: str | None, tenant: str = DEFAULT_TENANT
) -> dict[str, Any]:
    if not isinstance(raw, dict) or set(raw) != {"version"}:
        raise ValidationError("migrate body must contain exactly a version string")
    target = _identifier(raw["version"], "version")

    def apply() -> dict[str, Any]:
        row = self.store.connection.execute(
            "SELECT workflow_id, workflow_version FROM executions WHERE tenant = ? AND id = ?",
            (tenant, execution_id),
        ).fetchone()
        if row is None:
            raise NotFoundError(f"execution {execution_id} was not found")
        workflow_id = row["workflow_id"]
        target_row = self.store.connection.execute(
            "SELECT 1 FROM workflow_versions WHERE tenant = ? AND workflow_id = ? AND version = ?",
            (tenant, workflow_id, target),
        ).fetchone()
        if target_row is None:
            raise NotFoundError(f"workflow {workflow_id} version {target} was not found")
        # get_execution settles a due timeout first, so a deadline that has
        # elapsed takes precedence over the migration, as it does for every
        # other operation.
        state = self.get_execution(execution_id, tenant)
        if state["status"] != "running":
            raise ConflictError(f"execution {execution_id} is not running")
        current = row["workflow_version"]
        if target == current:
            # Already bound to the target: report the current state without
            # appending an event or writing a checkpoint.
            return state
        document, _ = self._load_workflow(workflow_id, tenant, target)
        workflow = Workflow.parse(document)
        self._reconcile_state_for_definition(state, workflow)
        # The payload carries the target revision's structural skeleton so
        # replay can rebuild the migration point from the event stream
        # alone, exactly as it does from the execution_started record.
        payload: dict[str, Any] = {"from_version": current, "to_version": target}
        payload["loops"] = {
            node.id: _new_loop_state() for node in workflow.nodes if node.kind == "loop"
        }
        declared_maps = _declared_map_states(workflow)
        if declared_maps:
            payload["maps"] = declared_maps
        if _has_approval_points(workflow):
            payload["waiting_approval"] = None
            payload["approvals"] = []
        self._append(execution_id, "version_migrated", payload, tenant)
        state["version"] = target
        self.store.connection.execute(
            "UPDATE executions SET state = ?, workflow_version = ? WHERE tenant = ? AND id = ?",
            (self.store.encode(state), target, tenant, execution_id),
        )
        # The migration is recorded at the same node boundary: checkpoint
        # the rebound summary at the migration event's position so recovery
        # resumes on the new version without replaying it.
        self._write_checkpoint(execution_id, state, tenant)
        return state

    with self._operation():
        # Scope the operation to the target tag so two migrations of the
        # same execution to different versions sharing one key conflict,
        # exactly like two version declarations do.
        return self._idempotent(key, f"migrate:{execution_id}:{target}", apply, tenant)

def _lease_row(self, execution_id: str, tenant: str) -> Any:
    return self.store.connection.execute(
        "SELECT worker_id, lease_seconds, expires_at, heartbeat_at FROM leases "
        "WHERE tenant = ? AND execution_id = ?",
        (tenant, execution_id),
    ).fetchone()

@staticmethod
def _lease_payload(worker_id: str, lease_seconds: float, expires_at: float, heartbeat_at: float) -> dict[str, Any]:
    return {

            map_state["status"] = "completed"
            map_state["outputs"] = [
                instance["output"]
                for instance in sorted(map_state["instances"], key=lambda item: item["index"])
            ]
            if "loop_id" in payload:
                # A nested map completes inside its iteration record; the
                # loop roll-up lifts it to the execution level when the
                # loop finishes, exactly like a body task.
                iteration = rebuilt["loops"][payload["loop_id"]]["iterations"][payload["iteration"] - 1]
                iteration["outputs"][payload["map_id"]] = map_state["outputs"]
                iteration["completed_nodes"].append(payload["map_id"])
            else:
                rebuilt["outputs"][payload["map_id"]] = map_state["outputs"]
                rebuilt["completed_nodes"].append(payload["map_id"])
        elif event_type == "map_reexpanded" and rebuilt is not None:
            # A re-expansion replaces the whole instance lineage: the
            # regenerated instances queue from zero, earlier records are
            # discarded, and a node that had completed leaves the
            # completed list until the regenerated instances finish. The
            # following map_completed event (for an empty regeneration)
            # completes it again exactly as usual.
            map_state = self._replay_map_state(rebuilt, payload)
            map_state["instances"] = [_new_map_instance(index) for index in range(payload["instance_count"])]
            map_state["outputs"] = []
            map_state["failure_reason"] = None
            map_state["status"] = "running"
            if "loop_id" in payload:
                container = rebuilt["loops"][payload["loop_id"]]["iterations"][payload["iteration"] - 1]
            else:
                container = rebuilt
            if payload["map_id"] in container["completed_nodes"]:
                container["completed_nodes"].remove(payload["map_id"])
            container["outputs"].pop(payload["map_id"], None)
        elif event_type == "instance_deleted" and rebuilt is not None:
            # A removal drops the instance record while every retained
            # instance keeps its index and order. When the removal empties
            # the map, the following map_completed event (appended by the
            # same operation) completes the node exactly as usual.
            map_state = self._replay_map_state(rebuilt, payload)
            map_state["instances"] = [
                item for item in map_state["instances"] if item["index"] != payload["index"]
            ]
        elif event_type == "instance_modified" and rebuilt is not None:
            # The rewrite affects only this one unadvanced instance; its
            # later completion records the output produced under the
            # rewritten input. The record is rebuilt rather than mutated so
            # the added input key keeps the same order as the stored state.
            map_state = self._replay_map_state(rebuilt, payload)
            position = next(
                position
                for position, item in enumerate(map_state["instances"])
                if item["index"] == payload["index"]
            )
            map_state["instances"][position] = _with_map_instance_input(
                map_state["instances"][position], payload["after"]
            )
        elif event_type == "iteration_started" and rebuilt is not None:
            loop_state = rebuilt["loops"][payload["loop_id"]]
            loop_state["status"] = "running"
            loop_state["current_iteration"] = payload["iteration"]
            iteration = _new_iteration()
            if payload.get("maps"):
                # A body declaring map nodes records a pending state per
                # nested map from the iteration's start.
                iteration["maps"] = {map_id: _new_map_state() for map_id in payload["maps"]}
            loop_state["iterations"].append(iteration)
        elif event_type == "loop_completed" and rebuilt is not None:
            loop_state = rebuilt["loops"][payload["loop_id"]]
            # Mirror the materialized roll-up: body nodes completed in any
            # iteration enter the execution-level completed list once, in
            # first completion order, followed by the loop node.
            listed = set(rebuilt["completed_nodes"])
            for iteration in loop_state["iterations"]:
                for node_id in iteration["completed_nodes"]:
                    if node_id not in listed:
                        rebuilt["completed_nodes"].append(node_id)
                        listed.add(node_id)
            loop_state["status"] = "completed"
            loop_state["end_reason"] = payload["reason"]
            rebuilt["completed_nodes"].append(payload["loop_id"])
        elif event_type == "approval_requested" and rebuilt is not None:
            waiting_record = {
                "node_id": payload["node_id"],
                "approvers": list(payload["approvers"]),
                **({"loop_id": payload["loop_id"], "iteration": payload["iteration"]} if "loop_id" in payload else {}),
            }
            if "map_id" in payload:
                waiting_record["map_id"] = payload["map_id"]
                waiting_record["index"] = payload["index"]
                instance = self._replay_map_instance(rebuilt, payload)
                instance["status"] = "waiting"
            rebuilt["waiting_approval"] = waiting_record
        elif event_type == "version_migrated" and rebuilt is not None:
            # Rebuild the migration point from the record alone: add the
            # structure the target revision introduces and rebind, while
            # keeping every pre-migration conclusion (and a parked approval
            # point) exactly as the earlier events rebuilt it.
            for loop_id in payload.get("loops", {}):
                if loop_id not in rebuilt["loops"]:
                    rebuilt["loops"][loop_id] = _new_loop_state()
            for map_id, map_state in payload.get("maps", {}).items():
                if map_id not in rebuilt.get("maps", {}):
                    rebuilt.setdefault("maps", {})[map_id] = map_state
            if "approvals" in payload and "approvals" not in rebuilt:
                rebuilt["waiting_approval"] = None
                rebuilt["approvals"] = []
            rebuilt["version"] = payload["to_version"]
        elif event_type == "approval_decided" and rebuilt is not None:
            verdict = payload["decision"]
            record = {
                "node_id": payload["node_id"],
                "approver": payload["approver"],
                "decision": verdict,
                "reason": payload.get("reason"),
            }
            if "loop_id" in payload:
                record["loop_id"] = payload["loop_id"]
                record["iteration"] = payload["iteration"]
            if "map_id" in payload:
                record["map_id"] = payload["map_id"]
                record["index"] = payload["index"]
            rebuilt["waiting_approval"] = None
            rebuilt["approvals"].append(record)
        elif event_type == "execution_completed" and rebuilt is not None:
            rebuilt["status"] = "completed"
        elif event_type == "execution_terminated" and rebuilt is not None:
            rebuilt["status"] = "terminated"
            rebuilt["termination_reason"] = payload["reason"]
            if "waiting_approval" in rebuilt:
                rebuilt["waiting_approval"] = None
            if "map_id" in payload:
                map_state = self._replay_map_state(rebuilt, payload)
                if "index" in payload:
                    instance = self._replay_map_instance(rebuilt, payload)
                    instance["status"] = "failed"
                    if payload["reason"] == "rejected":
                        # A rejected instance writes no node_failed event;
                        # its reason is the approval_decided record the
                        # replay already rebuilt for that instance.
                        text = next(
                            record.get("reason")
                            for record in reversed(rebuilt.get("approvals", []))
                            if record.get("map_id") == payload["map_id"]
                            and record.get("index") == payload["index"]
                            and record.get("loop_id") == payload.get("loop_id")
                            and record.get("iteration") == payload.get("iteration")
                        )
                        instance["failure_reason"] = text
                        map_state["failure_reason"] = text
                    else:
                        # Retry exhaustion: the reason was already recorded
                        # by the instance's final node_failed event.
                        map_state["failure_reason"] = instance["failure_reason"]
                map_state["status"] = "failed"
            if payload["reason"] in ("retries_exhausted", "rejected") and "node_id" in payload:
                rebuilt["failed_nodes"].append(payload["node_id"])
    if rebuilt is None:
        raise ConflictError("execution event stream has no start event")
    return {"consistent": rebuilt == stored, "execution": rebuilt}

def _append(
    self,
    execution_id: str,
    event_type: str,
    payload: dict[str, Any],
    tenant: str = DEFAULT_TENANT,
    occurred_at: str | None = None,
) -> None:
    if occurred_at is None:
        occurred_at = self.store.now()
    row = self.store.connection.execute(
        "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM events "
        "WHERE tenant = ? AND execution_id = ?",
        (tenant, execution_id),
    ).fetchone()
    self.store.connection.execute(
        "INSERT INTO events(tenant, execution_id, sequence, type, payload, occurred_at) VALUES (?, ?, ?, ?, ?, ?)",
        (tenant, execution_id, row["sequence"], event_type, self.store.encode(payload), occurred_at),
    )
    if event_type in NOTIFY_EVENT_TYPES:
        # Queue targets are fed in the same transaction as the event, so a
        # rolled-back operation never leaves a queued message behind.
        self._enqueue_queue_messages(execution_id, row["sequence"], event_type, payload, tenant)
        # Buffered, not delivered: the surrounding operation may still roll
        # back. The outermost _operation scope delivers after the commit.
        self._local.pending = getattr(self._local, "pending", []) + [
            {
                "tenant": tenant,
                "execution_id": execution_id,
                "sequence": row["sequence"],
                "type": event_type,
                "payload": payload,
            }
        ]

def _write_checkpoint(
    self, execution_id: str, state: dict[str, Any], tenant: str = DEFAULT_TENANT
) -> None:
    """Persist the state summary and event position at a node boundary."""
    event_row = self.store.connection.execute(
        "SELECT COALESCE(MAX(sequence), 0) AS sequence FROM events WHERE tenant = ? AND execution_id = ?",
        (tenant, execution_id),
    ).fetchone()
    checkpoint_row = self.store.connection.execute(
        "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM checkpoints "
        "WHERE tenant = ? AND execution_id = ?",
        (tenant, execution_id),
    ).fetchone()
    document = {"state": state, "event_sequence": event_row["sequence"]}
    self.store.connection.execute(
        "INSERT INTO checkpoints(tenant, execution_id, sequence, event_sequence, document, created_at) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (tenant, execution_id, checkpoint_row["sequence"], event_row["sequence"], self.store.encode(document), self.store.now()),
    )
